mapper.select:
select  

 order by coalesce(e.equip_cd, c.class_cd), i.item_cd
 limit #{limit}

mapper.update:
update cms_equip_spare
   set install_qty = #{s.installQty}, key_spare_yn = #{s.keySpareYn}, use_yn = #{s.useYn}, remark = #{s.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where spare_id = #{s.spareId} and row_ver = #{s.rowVer}

mapper.select:
select p.part_id, p.mwo_id, m.mwo_no, m.mwo_type, m.status as mwo_status,
       coalesce(e.equip_cd, a.asset_cd) as target_cd, coalesce(e.equip_nm, a.asset_nm) as target_nm,
       i.item_cd, i.item_nm, p.qty, p.unit_cd, coalesce(m.finished_at, p.created_at) as used_at, p.created_at, p.created_by
  from cms_mwo_part p
  join cms_mwo m on m.mwo_id = p.mwo_id
  join mst_item i on i.item_id = p.item_id
  left join mst_equip e on e.equip_id = m.equip_id
  left join mst_phys_asset a on a.asset_id = m.asset_id
 where coalesce(m.finished_at, p.created_at) >= #{from} and coalesce(m.finished_at, p.created_at) < #{to}
   and m.status <> 'CANCELLED'
   and m.equip_id = #{equipId}
   and e.class_id = #{classId}
   and p.item_id = #{itemId}
 order by coalesce(m.finished_at, p.created_at) desc, p.part_id desc
 limit #{limit}
